import Foundation
import Logging
import XCTest
@testable import ClientRuntime

final class MockLogHandler: LogHandler {
    var logLevel: Logger.Level = .info
    var metadata: Logger.Metadata = [:]

    private let lock = NSLock()
    private(set) var messages: [String] = []

    func log(level: Logger.Level,
             message: Logger.Message,
             metadata: Logger.Metadata?,
             source: String,
             file: String,
             function: String,
             line: UInt) {
        lock.lock()
        messages.append("\(message)")
        lock.unlock()
    }

    subscript(metadataKey metadataKey: String) -> Logger.Metadata.Value? {
        get { metadata[metadataKey] }
        set { metadata[metadataKey] = newValue }
    }
}

final class MockSDKLogHandlerFactory: SDKLogHandlerFactory {
    let label: String
    let handler: MockLogHandler
    private let lock = NSLock()
    private var _constructCallCount = 0

    init(label: String) {
        self.label = label
        self.handler = MockLogHandler()
    }

    var constructCallCount: Int {
        lock.lock()
        defer { lock.unlock() }
        return _constructCallCount
    }

    func construct(label: String) -> LogHandler {
        lock.lock()
        _constructCallCount += 1
        lock.unlock()
        return handler
    }
}

final class SDKLoggingSystemTests: XCTestCase {

    func testLoggingSystemInitializationIsIdempotentAndThreadSafe() {
        let testFactory = MockSDKLogHandlerFactory(label: "test-label")
        SDKLoggingSystem.add(logHandlerFactory: testFactory)

        SDKLoggingSystem.initialize(defaultLogLevel: .info)
        SDKLoggingSystem.initialize(defaultLogLevel: .error)
        SDKLoggingSystem.initialize(logLevel: .error)
        SDKLoggingSystem.initialize()
        SDKLoggingSystem.initialize(logLevel: .trace)

        let factoryLogger = Logger(label: "test-label")
        factoryLogger.info("hello from registered factory")
        XCTAssertEqual(testFactory.handler.messages, ["hello from registered factory"])
        XCTAssertGreaterThanOrEqual(testFactory.constructCallCount, 1)

        let defaultLogger = Logger(label: "unregistered-label")
        defaultLogger.info("hello from default handler")
        XCTAssertTrue(defaultLogger.logLevel == .info)

        let group = DispatchGroup()
        for _ in 0..<100 {
            DispatchQueue.global().async(group: group) {
                SDKLoggingSystem.initialize()
                SDKLoggingSystem.initialize(logLevel: .debug)
                SDKLoggingSystem.add(logHandlerFactory: MockSDKLogHandlerFactory(label: "unused-label"))
            }
        }
        XCTAssertEqual(group.wait(timeout: .now() + 10), .success)
    }

    func testAddingLogHandlerFactoryConcurrentlyIsSafe() {
        let labels = (0..<50).map { "concurrent-factory-\($0)" }
        let factories = labels.map { MockSDKLogHandlerFactory(label: $0) }

        let group = DispatchGroup()
        for factory in factories {
            DispatchQueue.global().async(group: group) {
                SDKLoggingSystem.add(logHandlerFactory: factory)
            }
        }
        XCTAssertEqual(group.wait(timeout: .now() + 10), .success)

        for factory in factories {
            let logger = Logger(label: factory.label)
            logger.info("message for \(factory.label)")
            XCTAssertEqual(factory.handler.messages.last, "message for \(factory.label)")
        }
    }
}

