// Copyright Amazon.com, Inc. or its affiliates. All Rights Reserved.
// SPDX-License-Identifier: Apache-2.0.

import AwsCommonRuntimeKit
import Foundation

public enum HashFunction {
    /// CRC-32 checksum
    case crc32
    /// CRC-32C Castagnoli checksum
    case crc32c
    /// SHA-1 hash
    case sha1
    /// SHA-256 hash
    case sha256
    /// MD5 hash
    case md5

    /// Returns the hash function corresponding to the given string, or `nil` if the string
    /// does not match any supported algorithm. The string is matched case-insensitively.
    /// - Parameter string: The string identifying the hash function
    /// - Returns: The matching `HashFunction`, or `nil` if none match
    public static func from(string: String) -> HashFunction? {
        switch string.lowercased() {
        case "crc32":
            return .crc32
        case "crc32c":
            return .crc32c
        case "sha1":
            return .sha1
        case "sha256":
            return .sha256
        case "md5":
            return .md5
        default:
            return nil
        }
    }

    /// Whether this hash function is a valid flexible checksum algorithm.
    /// CRC32, CRC32C, SHA1, and SHA256 are supported; MD5 is not a valid flexible
    /// checksum algorithm but is still available for computation.
    public var isSupported: Bool {
        switch self {
        case .crc32, .crc32c, .sha1, .sha256:
            return true
        case .md5:
            return false
        }
    }

    /// Computes the hash of the given data.
    /// - Parameter data: The data to compute the hash of
    /// - Returns: A `HashResult` holding either the computed checksum (for CRC32/CRC32C)
    /// or the computed hash data (for SHA1/SHA256/MD5)
    /// - Throws: `HashError.hashingFailed` if the underlying CRT call fails
    public func computeHash(of data: Data) throws -> HashResult {
        do {
            switch self {
            case .crc32:
                return .integer(try data.computeCRC32())
            case .crc32c:
                return .integer(try data.computeCRC32C())
            case .sha1:
                return .data(try data.computeSHA1())
            case .sha256:
                return .data(try data.computeSHA256())
            case .md5:
                return .data(try data.computeMD5())
            }
        } catch {
            throw HashError.hashingFailed(reason: "\(error)")
        }
    }
}

public enum HashResult {
    /// The computed hash data (for SHA1, SHA256, and MD5)
    case data(Data)
    /// The computed checksum integer (for CRC32 and CRC32C)
    case integer(UInt32)
}

public enum HashError: Error {
    /// The provided input was invalid
    case invalidInput
    /// The underlying hash computation failed
    case hashingFailed(reason: String)
}

extension HashResult {
    /// Returns a hexadecimal string representation of the hash result.
    /// Checksum integers are formatted with 8 characters (e.g., `%08x`), and
    /// hash data bytes are formatted with 2 characters each (e.g., `%02x`).
    public func toHexString() -> String {
        switch self {
        case .data(let data):
            return data.map { String(format: "%02x", $0) }.joined()
        case .integer(let value):
            return String(format: "%08x", value)
        }
    }
}

