    }

    func testCRC32C() throws {
        let data = Data([0xFF, 0xFE, 0xFD, 0xFC])
        let result = try HashFunction.crc32c.computeHash(of: data)
        switch result {
        case .integer(let checksum):
            XCTAssertEqual(checksum, 0x6eabae9b)
        case .data:
            XCTFail("Expected checksum integer for CRC32C")
        }
        XCTAssertEqual(result.toHexString(), "6eabae9b")
    }

    func testSHA1() throws {
        let data = Data([0xFF, 0xFE, 0xFD, 0xFC])
        let result = try HashFunction.sha1.computeHash(of: data)
        switch result {
