        case .integer:
            XCTFail("Expected hash data for SHA1")
        }
        XCTAssertEqual(result.toHexString(), "0037c9b5683c0e8d8ca6714db2f1519b232e10e2")
    }

    func testSHA256() throws {
        let data = Data([0xFF, 0xFE, 0xFD, 0xFC])
        let result = try HashFunction.sha256.computeHash(of: data)
        switch result {
