            XCTAssertEqual(hashedData.base64EncodedString(), "jCosV0rEcc6HWQwT8O/bQr0ssZuxhJM3nUW/zJBgtlc=")
        case .integer:
            XCTFail("Expected hash data for SHA256")
        }
        XCTAssertEqual(result.toHexString(), "8c2a2c574ac471ce87590c13f0efdb42bd2cb19bb18493379d45bfcc9060b657")
    }

    func testMD5() throws {
        let data = Data([0xFF, 0xFE, 0xFD, 0xFC])
        let result = try HashFunction.md5.computeHash(of: data)
        switch result {
        case .data(let hashedData):
            XCTAssertEqual(hashedData.base64EncodedString(), "ilWq/WLcPzYHQ8fAzwCCLg==")
        case .integer:
            XCTFail("Expected hash data for MD5")
        }
        XCTAssertEqual(result.toHexString(), "8a55aafd62dc3f360743c7c0cf00822e")
    }

    func testFromStringIsCaseInsensitive() {
        XCTAssertEqual(HashFunction.from(string: "crc32"), .crc32)
        XCTAssertEqual(HashFunction.from(string: "CRC32C"), .crc32c)
        XCTAssertEqual(HashFunction.from(string: "Sha1"), .sha1)
        XCTAssertEqual(HashFunction.from(string: "SHA256"), .sha256)
        XCTAssertEqual(HashFunction.from(string: "mD5"), .md5)
    }

    func testFromStringReturnsNilForUnknownString() {
        XCTAssertNil(HashFunction.from(string: "unknown"))
        XCTAssertNil(HashFunction.from(string: "crc64"))
        XCTAssertNil(HashFunction.from(string: ""))
    }

    func testIsSupported() {
        XCTAssertTrue(HashFunction.crc32.isSupported)
        XCTAssertTrue(HashFunction.crc32c.isSupported)
        XCTAssertTrue(HashFunction.sha1.isSupported)
        XCTAssertTrue(HashFunction.sha256.isSupported)
        XCTAssertFalse(HashFunction.md5.isSupported)
    }
}

