        case .data(let data):
            guard let data = data else { return output }
            let computed = try selectedAlgorithm.computeHash(of: data).toBase64String()
            guard computed == expectedChecksum else {
                throw FlexibleChecksumsError.checksumMismatch(
                    responseChecksum: expectedChecksum,
                    computedChecksum: computed,
                    headerName: headerName
