            }
        case .stream:
            guard let logger = context.getLogger() else { return output }
            logger.error("Flexible checksum validation on streaming payloads is not supported; skipping validation.")
        default:
            guard let logger = context.getLogger() else { return output }
            logger.error("Unhandled case for flexible checksum validation")
        }

        return output
    }

    /// Selects the checksum header to validate using the configured priority ordering.
    /// CRC32C has the highest priority, followed by CRC32, SHA1, and SHA256.
    private func selectChecksumAlgorithm(from headers: Headers) -> HashFunction? {
        let supportedCheckums = FlexibleChecksumsMiddleware.supportedChecksums.sorted()
        return supportedCheckums.first { headers.exists(name: "x-amz-checksum-\($0.toString())") }
    }
