extension HashFunction {
    /// The priority of this checksum algorithm when more than one checksum header is present.
    /// A lower value indicates a higher priority (CRC32C has the highest priority).
    public var checksumPriority: Int {
        switch self {
        case .crc32c:
            return 0
        case .crc32:
            return 1
        case .sha1:
            return 2
        case .sha256:
            return 3
        case .md5:
            return 4
        }
    }

    /// Returns the string representation of this hash function, as used in header names
    public func toString() -> String {
        switch self {
        case .crc32:
            return "crc32"
        case .crc32c:
            return "crc32c"
        case .sha1:
            return "sha1"
        case .sha256:
            return "sha256"
        case .md5:
            return "md5"
        }
    }

    /// Returns the hash functions that correspond to the given strings, preserving order.
    /// Strings that do not match any supported algorithm are dropped.
    public static func fromList(list: [String]) -> [HashFunction] {
        return list.compactMap { from(string: $0) }
    }
}

extension HashFunction: Comparable {
    public static func < (lhs: HashFunction, rhs: HashFunction) -> Bool {
