import AwsCommonRuntimeKit
import Foundation

public struct FlexibleChecksumsRequestMiddleware<OperationStackOutput>: Middleware {
    public let id: String = "FlexibleChecksumsRequest"

    /// Attribute keys used to configure the flexible checksums request middleware
    public struct Attributes {
        /// The checksum algorithm to use for computing the checksum of the request payload.
        /// When unset, the middleware skips processing without error (checksums are opt-in).
        public static let checksumAlgorithm = AttributeKey<HashFunction>(name: "ChecksumAlgorithm")
    }

    public init() {}

    public func handle<H>(context: Context,
                          input: MInput,
                          next: H) async throws -> MOutput
    where H: Handler,
    Self.MInput == H.Input,
    Self.MOutput == H.Output,
    Self.Context == H.Context {

        // Flexible checksums are opt-in. If no checksum algorithm is configured, skip without error.
        guard let checksumAlgorithm = context.attributes.get(key: Attributes.checksumAlgorithm) else {
            return try await next.handle(context: context, input: input)
        }

        switch input.body {
        case .data(let data):
            guard let data = data else {
                return try await next.handle(context: context, input: input)
            }
            let result = try checksumAlgorithm.computeHash(of: data)
            input.headers.update(name: "x-amz-checksum-\(checksumAlgorithm.toString())", value: result.toBase64String())
            input.headers.update(name: "x-amz-sdk-checksum-algorithm", value: checksumAlgorithm.toString())
        case .stream:
            guard let logger = context.getLogger() else {
                return try await next.handle(context: context, input: input)
            }
            logger.error("Flexible checksums are not supported for streaming payloads; skipping checksum computation.")
        default:
            guard let logger = context.getLogger() else {
                return try await next.handle(context: context, input: input)
            }
            logger.error("Unhandled case for flexible checksums")
        }

        return try await next.handle(context: context, input: input)
    }

    public typealias MInput = SdkHttpRequestBuilder
    public typealias MOutput = OperationOutput<OperationStackOutput>
    public typealias Context = HttpContext
}
