// Copyright Amazon.com, Inc. or its affiliates. All Rights Reserved.
// SPDX-License-Identifier: Apache-2.0.

import AwsCommonRuntimeKit
import Foundation

public struct FlexibleChecksumsResponseMiddleware<OperationStackOutput>: Middleware {
    public let id: String = "FlexibleChecksumsResponse"

    /// Attribute keys used to configure the flexible checksums response middleware
    public struct Attributes {
        /// The validation mode. When set to `.enabled`, the response checksum is validated against
        /// the checksum headers returned by the service. When unset or set to `.disabled`, the
        /// middleware skips processing without error.
        public static let validationMode = AttributeKey<ValidationMode>(name: "ChecksumValidationMode")
    }

    /// Whether the response checksum should be validated
    public enum ValidationMode: String {
        case enabled
        case disabled
    }

    /// The checksum algorithms to consider when selecting which header to validate, in priority order
    private let supportedChecksumAlgorithms: [HashFunction] = [.crc32c, .crc32, .sha1, .sha256]

    public init() {}

    public func handle<H>(context: Context,
                          input: MInput,
                          next: H) async throws -> MOutput
    where H: Handler,
    Self.MInput == H.Input,
    Self.MOutput == H.Output,
    Self.Context == H.Context {

        let output = try await next.handle(context: context, input: input)

        // Validation is opt-in. If the validation mode is not set to `.enabled`, skip without error.
        guard context.attributes.get(key: Attributes.validationMode) == .enabled else {
            return output
        }

        let response = output.httpResponse

        // Select the checksum header with the highest priority that is present in the response
        guard let selectedAlgorithm = selectChecksumAlgorithm(headers: response.headers) else {
            return output
        }
        let headerName = "x-amz-checksum-\(selectedAlgorithm.toString())"
        guard let expectedChecksum = response.headers.value(for: headerName) else {
            return output
        }

        switch response.body {
        case .data(let data):
            guard let data = data else {
                return output
            }
            let computedChecksum = try selectedAlgorithm.computeHash(of: data).toBase64String()
            guard computedChecksum == expectedChecksum else {
                throw FlexibleChecksumsError.checksumMismatch(
                    responseChecksum: expectedChecksum,
                    computedChecksum: computedChecksum,
                    headerName: headerName
                )
            }
        case .stream:
            guard let logger = context.getLogger() else {
                return output
            }
            logger.error("Flexible checksum validation is not supported for streaming payloads; skipping validation.")
        default:
            guard let logger = context.getLogger() else {
                return output
            }
            logger.error("Unhandled case for flexible checksum validation")
        }

        return output
    }

    /// Selects the checksum algorithm whose header is present in the response, using priority ordering.
    /// CRC32C has the highest priority, followed by CRC32, SHA1, and SHA256.
    private func selectChecksumAlgorithm(headers: Headers) -> HashFunction? {
        return supportedChecksumAlgorithms.sorted().first { headers.exists(name: "x-amz-checksum-\($0.toString())") }
    }

    public typealias MInput = SdkHttpRequest
    public typealias MOutput = OperationOutput<OperationStackOutput>
    public typealias Context = HttpContext
}

public enum FlexibleChecksumsError: Error {
    /// The response checksum header value did not match the computed checksum of the response body
    case checksumMismatch(responseChecksum: String, computedChecksum: String, headerName: String)
}
