extension HashFunction: Comparable {
    /// Compares two `HashFunction` values by checksum priority, so that the
    /// highest priority checksum algorithm (CRC32C) sorts first.
    /// - Parameters:
    ///   - lhs: The first `HashFunction` to compare.
    ///   - rhs: The second `HashFunction` to compare.
    /// - Returns: `true` if `lhs` has a higher priority than `rhs`, otherwise `false`.
    public static func < (lhs: HashFunction, rhs: HashFunction) -> Bool {
        return lhs.checksumPriority < rhs.checksumPriority
    }
