import AwsCommonRuntimeKit
import XCTest
import SmithyTestUtil

class FlexibleChecksumsResponseMiddlewareTests: XCTestCase {
    private var builtContext: HttpContext!
    private var stack: OperationStack<MockInput, MockOutput>!

    private let payloadData = Data([0xFF, 0xFE, 0xFD, 0xFC])
    private let crc32Checksum = "VQKm8A=="
    private let crc32cChecksum = "bquumw=="
    private let sha256Checksum = "jCosV0rEcc6HWQwT8O/bQr0ssZuxhJM3nUW/zJBgtlc="

    override func setUp() async throws {
        try await super.setUp()
        CommonRuntimeKit.initialize()
        builtContext = HttpContextBuilder()
                  .withMethod(value: .get)
                  .withPath(value: "/")
                  .withEncoder(value: JSONEncoder())
                  .withDecoder(value: JSONDecoder())
                  .withOperation(value: "Test Operation")
                  .build()
        stack = OperationStack<MockInput, MockOutput>(id: "Test Operation")
    }

    func testMiddlewareSkipsWhenValidationModeNotConfigured() async throws {
        addFlexibleChecksumsResponseMiddleware()
        try await assertResponseValidation(headers: ["x-amz-checksum-crc32": "invalid"], expectError: false)
    }

    func testMiddlewareSkipsWhenValidationModeDisabled() async throws {
        setValidationMode(on: &builtContext, mode: .disabled)
        addFlexibleChecksumsResponseMiddleware()
        try await assertResponseValidation(headers: ["x-amz-checksum-crc32": "invalid"], expectError: false)
    }

    func testValidChecksumPasses() async throws {
        setValidationMode(on: &builtContext)
        addFlexibleChecksumsResponseMiddleware()
        try await assertResponseValidation(headers: ["x-amz-checksum-crc32": crc32Checksum], expectError: false)
    }

    func testMismatchedChecksumThrows() async throws {
        setValidationMode(on: &builtContext)
        addFlexibleChecksumsResponseMiddleware()
        do {
            try await assertResponseValidation(headers: ["x-amz-checksum-crc32": "invalid"], expectError: false)
            XCTFail("Expected FlexibleChecksumsError.checksumMismatch to be thrown")
        } catch let error as FlexibleChecksumsError {
            switch error {
            case .checksumMismatch(let responseChecksum, let computedChecksum, let headerName):
                XCTAssertEqual(responseChecksum, "invalid")
                XCTAssertEqual(computedChecksum, crc32Checksum)
                XCTAssertEqual(headerName, "x-amz-checksum-crc32")
            }
        }
    }

    func testPreferenceOrderSelectsHighestPriorityChecksum() async throws {
        // The response contains both a CRC32 and a SHA256 checksum, where the CRC32 checksum is
        // correct and matches the response body. Both CRC32C and CRC32 are higher priority than
        // SHA256, so the highest priority header present (CRC32) must be validated.
        setValidationMode(on: &builtContext)
        addFlexibleChecksumsResponseMiddleware()
        try await assertResponseValidation(
            headers: ["x-amz-checksum-crc32": crc32Checksum, "x-amz-checksum-sha256": "invalid"],
            expectError: false
        )
    }

    func testPreferenceOrderValidatesHighestPriorityPresentChecksum() async throws {
        // The response contains an incorrect CRC32 checksum and a correct SHA256 checksum.
        // CRC32 has a higher priority than SHA256, so the middleware must validate CRC32 and
        // throw a checksum mismatch error even though the SHA256 checksum is valid.
        setValidationMode(on: &builtContext)
        addFlexibleChecksumsResponseMiddleware()
        do {
            try await assertResponseValidation(
                headers: ["x-amz-checksum-crc32": "invalid", "x-amz-checksum-sha256": sha256Checksum],
                expectError: false
            )
            XCTFail("Expected FlexibleChecksumsError.checksumMismatch to be thrown")
        } catch let error as FlexibleChecksumsError {
            switch error {
            case .checksumMismatch(let responseChecksum, _, let headerName):
                XCTAssertEqual(responseChecksum, "invalid")
                XCTAssertEqual(headerName, "x-amz-checksum-crc32")
            }
        }
    }

    func testCRC32CChecksumValidation() async throws {
        setValidationMode(on: &builtContext)
        addFlexibleChecksumsResponseMiddleware()
        try await assertResponseValidation(headers: ["x-amz-checksum-crc32c": crc32cChecksum], expectError: false)
    }

    func testStreamingPayloadValidationSkips() async throws {
        setValidationMode(on: &builtContext)
        addFlexibleChecksumsResponseMiddleware()
        let mockHandler = MockHandler<MockOutput> { (_, input) in
            let httpResponse = HttpResponse(headers: Headers(["x-amz-checksum-crc32": "invalid"]),
                                            body: .stream(BufferedStream()),
                                            statusCode: .ok)
            let mockOutput = try MockOutput(httpResponse: httpResponse, decoder: nil)
            return OperationOutput<MockOutput>(httpResponse: httpResponse, output: mockOutput)
        }
        let output = try await stack.handleMiddleware(context: builtContext, input: MockInput(), next: mockHandler)
        XCTAssertNotNil(output.output)
    }

    private func addFlexibleChecksumsResponseMiddleware() {
        stack.deserializeStep.intercept(
            position: .before,
            middleware: FlexibleChecksumsResponseMiddleware<MockOutput>()
        )
    }

    private func setValidationMode(on context: inout HttpContext!, mode: FlexibleChecksumsResponseMiddleware<MockOutput>.ValidationMode = .enabled) {
        context = HttpContextBuilder()
            .withMethod(value: .get)
            .withPath(value: "/")
            .withEncoder(value: JSONEncoder())
            .withDecoder(value: JSONDecoder())
            .withOperation(value: "Test Operation")
            .with(key: FlexibleChecksumsResponseMiddleware<MockOutput>.Attributes.validationMode, value: mode)
            .build()
    }

    private func assertResponseValidation(headers: [String: String],
                                          expectError: Bool,
                                          file: StaticString = #file,
                                          line: UInt = #line) async throws {
        let mockHandler = MockHandler<MockOutput> { (_, input) in
            let httpResponse = HttpResponse(headers: Headers(headers), body: .data(self.payloadData), statusCode: .ok)
            let mockOutput = try MockOutput(httpResponse: httpResponse, decoder: nil)
            return OperationOutput<MockOutput>(httpResponse: httpResponse, output: mockOutput)
        }
        let output = try await stack.handleMiddleware(context: builtContext, input: MockInput(), next: mockHandler)
        XCTAssertNotNil(output.output, file: file, line: line)
    }
}

