// API Reference: https://awslabs.github.io/smithy/1.0/spec/core/http-traits.html#httpchecksum-trait
private fun OperationShape.isChecksumRequired(): Boolean {
    val httpChecksumTrait = getTrait<HttpChecksumTrait>()
    // When the operation supports flexible checksums (i.e., it has a request algorithm member),
    // the flexible checksums middleware computes the checksum and Content-MD5 is not required.
    if (httpChecksumTrait?.requestAlgorithmMember?.isPresent == true) {
        return false
    }
    return httpChecksumTrait?.isRequestChecksumRequired == true || hasTrait<HttpChecksumRequiredTrait>()
}

