def nexusUrl = 'http://mirror.proxy.hpc:8081/repository/maven-public/'

settingsEvaluated { settings ->
    settings.pluginManagement.repositories {
        clear()
        maven { url nexusUrl }
    }
}

allprojects {
    buildscript {
        repositories {
            all { ArtifactRepository repo ->
                if (repo instanceof MavenArtifactRepository && repo.url.toString().startsWith('http://')) {
                    repo.allowInsecureProtocol = true
                }
            }
            maven { url nexusUrl }
        }
    }
    repositories {
        all { ArtifactRepository repo ->
            if (repo instanceof MavenArtifactRepository) {
                def url = repo.url.toString()
                if (url.startsWith('https://repo1.maven.org') ||
                    url.startsWith('https://jcenter.bintray.com') ||
                    url.startsWith('https://plugins.gradle.org') ||
                    url.startsWith('https://repo.maven.apache.org') ||
                    url.startsWith('https://dl.google.com')) {
                    remove repo
                }
                if (url.startsWith('http://')) {
                    repo.allowInsecureProtocol = true
                }
            }
        }
        maven { url nexusUrl }
    }
}

