import os
import shutil
import re

SRC = "/opt/mirror-config/.gradle/caches/modules-2/files-2.1"
DST = "/tmp/opencode/m2repo"

count = 0
for group in os.listdir(SRC):
    gpath = os.path.join(SRC, group)
    if not os.path.isdir(gpath):
        continue
    for artifact in os.listdir(gpath):
        apath = os.path.join(gpath, artifact)
        if not os.path.isdir(apath):
            continue
        if artifact.startswith("."):
            # marker-like dirs e.g. org.gradle.kotlin.kotlin-dsl.gradle.plugin nested as artifact
            # layout already has group/artifact/version/hash/file so just continue normal handling
            pass
        for version in os.listdir(apath):
            vpath = os.path.join(apath, version)
            if not os.path.isdir(vpath):
                continue
            for sha in os.listdir(vpath):
                spath = os.path.join(vpath, sha)
                if not os.path.isdir(spath):
                    continue
                for fname in os.listdir(spath):
                    src_file = os.path.join(spath, fname)
                    if not os.path.isfile(src_file):
                        continue
                    group_dirs = group.replace(".", "/")
                    dst_dir = os.path.join(DST, group_dirs, artifact, version)
                    os.makedirs(dst_dir, exist_ok=True)
                    dst_file = os.path.join(dst_dir, fname)
                    if not os.path.exists(dst_file):
                        shutil.copy2(src_file, dst_file)
                        count += 1
print(f"copied {count} files to {DST}")

def localRepo = 'file:///tmp/opencode/m2repo'

settingsEvaluated { settings ->
    settings.pluginManagement.repositories {
        clear()
        maven { url localRepo }
    }
}

allprojects {
    buildscript {
        repositories {
            clear()
            maven { url localRepo }
        }
    }
    repositories {
        clear()
        maven { url localRepo }
    }
}

